import type { ReactElement } from 'react';
import { ConvertibleUnit, FormatOptions, Unit } from '@dynatrace-sdk/units';
import type { StylingProps } from '../../../core/types/styling-props.js';
import { TruncationMode } from '../../../typography/TextEllipsis.js';
import { ColorPalette, CustomColorPalette } from '../../core/types/color-palette.js';
import { Formatter } from '../../core/types/formatter.js';
export interface TreeMapLeafNode {
    name: string;
    value: number;
}
export interface TreeMapClusterNode extends TreeMapLeafNode {
    nodes?: Array<TreeMapLeafNode>;
}
export interface TreeMapRootNode extends Omit<TreeMapLeafNode, 'name'> {
    nodes: Array<TreeMapClusterNode>;
    name?: string;
}
export interface TreeMapData {
    /** The tree root node. */
    tree: TreeMapRootNode;
    /** Optional unit to use for the tooltip. */
    unit?: string;
}
export interface TreeMapProps extends StylingProps {
    /** The tree map data to display. */
    data: TreeMapData;
    /**
     * Optional height of the chart.
     *
     * @defaultValue 400
     */
    height?: string | number;
    /**
     * Color palette to use for coloring the tree nodes. Nodes of height 1
     * get a color assigned from the palette. If the are more nodes than
     * colors, they are repeated. Nodes of height 2 get different shades
     * of their parents color assigned. The shading depends on the nodes
     * size compared to the biggest node.
     *
     * @defaultValue 'categorical'
     */
    colorPalette?: ColorPalette | CustomColorPalette;
    /**
     * Custom value formatter for the chart.
     */
    formatter?: Formatter | FormatOptions<Unit, ConvertibleUnit>;
    /**
     * The text truncation mode used for the chart legend.
     *
     * @defaultValue 'middle'
     */
    truncationMode?: TruncationMode;
    /**
     * The minimum area in px a node has to be to get rendered. Smaller
     * nodes get combined into an aggregated node.
     *
     * @defaultValue 0
     */
    minNodeSize?: number;
    /**
     * Show the loading indicator.
     *
     * @defaultValue false
     */
    loading?: boolean;
    /** Exposed callback to display series actions for a node  */
    seriesActions?: (node: TreeMapLeafNode) => ReactElement;
}
export interface TreeMapRef extends HTMLDivElement {
    /** Returns the current serialized config of the TreeMap.*/
    getConfig: () => string;
    /** Downloads TreeMap chart csv data .*/
    downloadData: () => void;
}
